import { isIPv6 } from "node:net";
/** TCP address of a listening server. A pipe or a closed server throws. */
export function tcpAddress(server) {
    const address = server.address();
    if (address === null || typeof address === "string") {
        throw new Error("server is not listening on a TCP port");
    }
    return address;
}
/** `http:` origin of a server bound to `host`; a wildcard bind is reached on 127.0.0.1. */
export function serveOrigin(host, port) {
    const reachable = host === "0.0.0.0" || host === "::" ? "127.0.0.1" : host;
    return `http://${isIPv6(reachable) ? `[${reachable}]` : reachable}:${port}`;
}
